import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

sym_matmul_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>

// Naive CUDA kernel for matrix multiplication
__global__ void matmul_kernel(const float* A, const float* B, float* C, int N) {
    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;

    if (row < N && col < N) {
        float val = 0.0f;
        for (int k = 0; k < N; ++k) {
            val += A[row * N + k] * B[k * N + col];
        }
        C[row * N + col] = val;
    }
}

torch::Tensor sym_matmul_cuda(torch::Tensor A, torch::Tensor B, int N) {
    // Ensure A and B are contiguous
    A = A.contiguous();
    B = B.contiguous();
    auto options = torch::TensorOptions().dtype(A.dtype()).device(A.device());
    auto C = torch::zeros({N, N}, options);

    dim3 block(16, 16);
    dim3 grid((N + block.x - 1) / block.x, (N + block.y - 1) / block.y);

    matmul_kernel<<<grid, block>>>(A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), N);

    return C;
}
""";

sym_matmul_cpp_source = "torch::Tensor sym_matmul_cuda(torch::Tensor A, torch::Tensor B, int N);"

sym_matmul = load_inline(
    name="sym_matmul",
    cpp_sources=sym_matmul_cpp_source,
    cuda_sources=sym_matmul_source,
    functions=["sym_matmul_cuda"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    verbose=False,
)

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()
        self.sym_matmul = sym_matmul

    def forward(self, A, B):
        A = A.cuda()
        B = B.cuda()
        N = A.size(0)
        return self.sym_matmul.sym_matmul_cuda(A, B, N)
